/**
 * Resolves a dependency specifier relative to a `package.json`, working in both the Node.js
 * CLI and the browser-based IDE worker.
 *
 * The browser IDE injects `require`/`require.resolve` into the module context. The only
 * difference from Node's built-ins is that the IDE versions are async — and awaiting a
 * non-async function is a noop, so `await require.resolve(...)` is safe in both environments
 * with no `node:module`/`createRequire` branch. Node ignores `fromPath` (it is not a
 * `{ paths }` options object, so resolution falls back to this module's location), while the
 * IDE uses it as the resolution base.
 *
 * @param specifier - The dependency to resolve (e.g. `@servicenow/isomorphic-rollup`).
 * @param fromPath - Absolute path to the `package.json` to resolve from.
 * @returns The absolute path to the resolved module entry point.
 */
export async function isomorphicRequireResolve(specifier: string, fromPath: string): Promise<string> {
    const resolve = require.resolve as unknown as (id: string, fromPath: string) => string | Promise<string>
    return resolve(specifier, fromPath)
}
